// Registry for the ahead-of-time compiled VU1 microprograms (vu1_aot_programs.cpp, generated by
// tools/vu1aot_gen from code images recorded with PS2X_VU1_CAPTURE=1).
//
// A program is identified by the hash of the whole 16 KB VU1 code memory, so compiled code only
// runs on exactly the image it was generated from; anything else stays on the interpreter.
// PS2X_VU1_AOT=0 turns compiled programs off.

#include "ps2_vu_fast_inl.h"
#include "runtime/ps2_perf.h"

#include <cstdio>
#include <cstdlib>
#include <mutex>
#include <set>

extern const Vu1AotProgram g_vu1AotPrograms[];
extern const size_t g_vu1AotProgramCount;

bool &Vu1Aot::enabledFlag()
{
    static bool on = []()
    {
        const char *env = std::getenv("PS2X_VU1_AOT");
        return !(env && *env == '0');
    }();
    return on;
}

Vu1Aot::Fn Vu1Aot::lookup(const uint8_t *code, uint32_t codeSize)
{
    if (!code || (codeSize != 16384u && codeSize != 4096u)) // VU1 or VU0 code memory
        return nullptr;
    const uint64_t hash = vufast::codeHash(code, codeSize);
    const Vu1AotProgram *found = nullptr;
    for (size_t i = 0; i < g_vu1AotProgramCount; ++i)
    {
        if (g_vu1AotPrograms[i].hash == hash)
        {
            found = &g_vu1AotPrograms[i];
            break;
        }
    }

    // One log line per distinct image: shows which microprograms run compiled on this PC.
    static std::mutex mutex;
    static std::set<uint64_t> seen;
    {
        std::lock_guard<std::mutex> lock(mutex);
        if (seen.insert(hash).second)
        {
            const char *unit = codeSize == 4096u ? "VU0" : "VU1";
            if (found)
                ps2perf::performanceNote("           %s microprogram image %016llx: compiled (%u pairs) - fast path", unit,
                                         static_cast<unsigned long long>(hash), found->pairs);
            else
                ps2perf::performanceNote("           %s microprogram image %016llx: not compiled - interpreter", unit,
                                         static_cast<unsigned long long>(hash));
            std::fprintf(stderr, "[%s-aot] image %016llx: %s\n", codeSize == 4096u ? "vu0" : "vu1",
                         static_cast<unsigned long long>(hash), found ? "compiled" : "interpreted");
        }
    }
    return found ? found->fn : nullptr;
}
